import{_ as t,o as r,c as a,a2 as o}from"./chunks/framework.D1rSJmVq.js";const m=JSON.parse('{"title":"Matrix Spec Map","description":"How hookshot maps to the Matrix specification","frontmatter":{"title":"Matrix Spec Map","description":"How hookshot maps to the Matrix specification","audience":["developer","architect","contributor"]},"headers":[],"relativePath":"reference/matrix-spec-map.md","filePath":"reference/matrix-spec-map.md","lastUpdated":1775244379000}'),s={name:"reference/matrix-spec-map.md"};function i(n,e,d,c,p,h){return r(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="matrix-specification-map" tabindex="-1">Matrix Specification Map <a class="header-anchor" href="#matrix-specification-map" aria-label="Permalink to &quot;Matrix Specification Map&quot;">​</a></h1><p>How hookshot uses the Matrix specification. This page maps hookshot concepts to the relevant spec sections.</p><h2 id="core-spec-dependencies" tabindex="-1">Core spec dependencies <a class="header-anchor" href="#core-spec-dependencies" aria-label="Permalink to &quot;Core spec dependencies&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Hookshot feature</th><th>Matrix spec section</th><th>How hookshot uses it</th></tr></thead><tbody><tr><td>Appservice registration</td><td><a href="https://spec.matrix.org/latest/application-service-api/" target="_blank" rel="noreferrer">Application Service API</a></td><td>Hookshot registers as an appservice to receive events and act as bot users</td></tr><tr><td>Bot messages</td><td><a href="https://spec.matrix.org/latest/client-server-api/#mroommessage" target="_blank" rel="noreferrer">m.room.message</a></td><td>All notifications sent as <code>m.room.message</code> with <code>msgtype: m.notice</code></td></tr><tr><td>Connection storage</td><td><a href="https://spec.matrix.org/latest/client-server-api/#room-state" target="_blank" rel="noreferrer">Room State Events</a></td><td><a href="./../architecture/connections">Connections</a> stored as custom state events (<code>uk.half-shot.matrix-hookshot.*</code>)</td></tr><tr><td>Room upgrades</td><td><a href="https://spec.matrix.org/latest/client-server-api/#mroomtombstone" target="_blank" rel="noreferrer">m.room.tombstone</a></td><td>Hookshot <a href="./../architecture/connections#room-migration">migrates connections</a> when rooms are upgraded</td></tr><tr><td>Power levels</td><td><a href="https://spec.matrix.org/latest/client-server-api/#mroompower_levels" target="_blank" rel="noreferrer">m.room.power_levels</a></td><td>Hookshot checks power levels before writing state events</td></tr><tr><td>Room membership</td><td><a href="https://spec.matrix.org/latest/client-server-api/#mroommember" target="_blank" rel="noreferrer">m.room.member</a></td><td>Bot auto-joins on invite, caches membership for <a href="./../understand/trust-and-boundaries#permission-system">permissions</a></td></tr><tr><td>Formatted messages</td><td><a href="https://spec.matrix.org/latest/client-server-api/#mroommessage-msgtypes" target="_blank" rel="noreferrer">org.matrix.custom.html</a></td><td>All notifications include <code>formatted_body</code> with HTML</td></tr><tr><td>User impersonation</td><td><a href="https://spec.matrix.org/latest/application-service-api/#identity-assertion" target="_blank" rel="noreferrer">Appservice identity assertion</a></td><td><a href="./../guides/operator/service-bots">Service bots</a> send messages as virtual users</td></tr><tr><td>Encryption</td><td><a href="https://spec.matrix.org/latest/client-server-api/#end-to-end-encryption" target="_blank" rel="noreferrer">E2EE / Megolm</a></td><td>Optional <a href="./../guides/operator/encryption">encryption support</a> for E2EE rooms</td></tr></tbody></table><h2 id="unstable-experimental-specs" tabindex="-1">Unstable/experimental specs <a class="header-anchor" href="#unstable-experimental-specs" aria-label="Permalink to &quot;Unstable/experimental specs&quot;">​</a></h2><table tabindex="0"><thead><tr><th>MSC</th><th>Status</th><th>Hookshot usage</th></tr></thead><tbody><tr><td><a href="https://github.com/matrix-org/matrix-spec-proposals/pull/2409" target="_blank" rel="noreferrer">MSC2409</a></td><td>Implemented in Synapse</td><td>Push ephemeral events to appservices (required for <a href="./../guides/operator/encryption">encryption</a>)</td></tr><tr><td><a href="https://github.com/matrix-org/matrix-spec-proposals/pull/3202" target="_blank" rel="noreferrer">MSC3202</a></td><td>Implemented in Synapse</td><td>Device masquerading for appservice encryption</td></tr><tr><td><a href="https://github.com/matrix-org/matrix-spec-proposals/pull/4203" target="_blank" rel="noreferrer">MSC4203</a></td><td>Draft</td><td>Improved appservice encryption</td></tr></tbody></table><h2 id="matrix-event-types-hookshot-sends" tabindex="-1">Matrix event types hookshot sends <a class="header-anchor" href="#matrix-event-types-hookshot-sends" aria-label="Permalink to &quot;Matrix event types hookshot sends&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Event type</th><th>Where</th><th>Purpose</th></tr></thead><tbody><tr><td><code>m.room.message</code> (msgtype: <code>m.notice</code>)</td><td>Rooms</td><td>All notifications and command responses</td></tr><tr><td><code>m.room.message</code> (msgtype: <code>m.text</code>)</td><td>Rooms</td><td>Some user-facing responses</td></tr><tr><td><code>m.reaction</code></td><td>Rooms</td><td>Response to <a href="./../integrations/github#emoji-reactions">emoji reaction commands</a></td></tr><tr><td>Custom state events (<code>uk.half-shot.matrix-hookshot.*</code>)</td><td>Room state</td><td><a href="./../reference/event-types">Connection configuration</a></td></tr></tbody></table><h2 id="matrix-event-types-hookshot-consumes" tabindex="-1">Matrix event types hookshot consumes <a class="header-anchor" href="#matrix-event-types-hookshot-consumes" aria-label="Permalink to &quot;Matrix event types hookshot consumes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Event type</th><th>Handler</th><th>Purpose</th></tr></thead><tbody><tr><td><code>m.room.message</code></td><td><a href="./../understand/event-lifecycle#outbound-matrix-to-external-service">Bridge.onRoomMessage</a></td><td>Bot command dispatch</td></tr><tr><td><code>m.room.member</code></td><td>Bridge.onRoomEvent</td><td>Membership cache for <a href="./../understand/trust-and-boundaries#permission-system">permissions</a></td></tr><tr><td><code>m.room.tombstone</code></td><td>Bridge.onRoomEvent</td><td><a href="./../architecture/connections#room-migration">Room upgrade migration</a></td></tr><tr><td><code>m.room.power_levels</code></td><td>Bridge.onRoomEvent</td><td>Power level tracking</td></tr><tr><td>Custom state events</td><td><a href="./../architecture/connections#connectionmanager">ConnectionManager</a></td><td>Connection creation and updates</td></tr><tr><td><code>m.reaction</code></td><td>Connection handlers</td><td><a href="./../integrations/github#emoji-reactions">Emoji reaction dispatch</a></td></tr></tbody></table><h2 id="appservice-registration" tabindex="-1">Appservice registration <a class="header-anchor" href="#appservice-registration" aria-label="Permalink to &quot;Appservice registration&quot;">​</a></h2><p>Hookshot&#39;s <a href="./../guides/operator/installation#create-the-registration-file">registration file</a> declares:</p><table tabindex="0"><thead><tr><th>Field</th><th>Value</th><th>Spec reference</th></tr></thead><tbody><tr><td><code>sender_localpart</code></td><td><code>hookshot</code></td><td><a href="https://spec.matrix.org/latest/application-service-api/#registration" target="_blank" rel="noreferrer">Appservice registration</a></td></tr><tr><td><code>namespaces.users</code></td><td><code>@_github_.*</code>, <code>@_gitlab_.*</code>, <code>@_jira_.*</code>, <code>@_webhooks_.*</code></td><td><a href="https://spec.matrix.org/latest/application-service-api/#registration" target="_blank" rel="noreferrer">User namespace</a></td></tr><tr><td><code>namespaces.aliases</code></td><td><code>#github_.+:domain</code></td><td><a href="https://spec.matrix.org/latest/application-service-api/#registration" target="_blank" rel="noreferrer">Alias namespace</a></td></tr><tr><td><code>rate_limited</code></td><td><code>false</code></td><td>Appservice requests are not rate limited</td></tr></tbody></table><p>See <a href="./../guides/operator/installation#create-the-registration-file">Installation: Create the registration file</a> for the full template.</p><h2 id="custom-event-types" tabindex="-1">Custom event types <a class="header-anchor" href="#custom-event-types" aria-label="Permalink to &quot;Custom event types&quot;">​</a></h2><p>Hookshot defines 15+ custom state event types for <a href="./../reference/event-types">connection storage</a>. These are not part of the Matrix spec — they use the <code>uk.half-shot.matrix-hookshot.</code> namespace (with one exception: <code>org.matrix.matrix-hookshot.openproject.*</code>).</p><p>Full list: <a href="./../reference/event-types">Reference: Event Types</a></p><h2 id="message-metadata" tabindex="-1">Message metadata <a class="header-anchor" href="#message-metadata" aria-label="Permalink to &quot;Message metadata&quot;">​</a></h2><p>Hookshot embeds structured metadata in <code>m.room.message</code> events using custom fields (e.g., <code>uk.half-shot.matrix-hookshot.github.repo</code>). These enable rich client rendering but are not part of the Matrix spec.</p><p>Full list: <a href="./../reference/event-types#message-metadata-event-types">Reference: Event Types — Message metadata</a></p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./../understand/what-is-hookshot">What is Hookshot</a> — System overview</li><li><a href="./../understand/event-lifecycle">Event Lifecycle</a> — How events flow</li><li><a href="./../architecture/connections">Architecture: Connections</a> — Connection state model</li><li><a href="./../reference/event-types">Reference: Event Types</a> — All custom event types</li><li><a href="./../guides/operator/installation">Installation</a> — Registration file setup</li><li><a href="./../guides/operator/encryption">Encryption</a> — E2EE configuration</li></ul>',22)])])}const f=t(s,[["render",i]]);export{m as __pageData,f as default};
